import math

def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """

    # Check if the input is an integer
    if not isinstance(a, int):
        raise TypeError("Input must be an integer.")

    # Check if the input is less than 100
    if a < 0 or a >= 100:
        raise ValueError("Input must be a non-negative integer less than 100.")

    # Function to check if a number is prime
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(math.sqrt(n)) + 1):
            if n % i == 0:
                return False
        return True

    # Find all prime factors of the input number
    prime_factors = set()
    for i in range(2, a + 1):
        while a % i == 0:
            prime_factors.add(i)
            a //= i

    # Check if the number of prime factors is 3
    if len(prime_factors) != 3:
        return False

    # Check if the prime factors are distinct
    if len(prime_factors) != len(set(prime_factors)):
        return False

    # Check if the prime factors are prime
    for factor in prime_factors:
        if not is_prime(factor):
            return False

    return True
